{
  "items": [
    {
      "item_id": "h071",
      "prompts": [
        "I'm choosing between laptop models and have five candidates with these specs: weight (kg) vs battery life (hours): (1.2, 8), (1.5, 12), (2.0, 15), (1.8, 10), (1.3, 11). I want light weight AND long battery. Identify which options can't be beaten on both criteria at once, and explain which ones I can safely eliminate."
      ],
      "rubric": [
        "Identifies (1.2, 8), (1.5, 12), (2.0, 15) — or the correct set of non-dominated points — as the trade-off frontier",
        "Explains why (1.8, 10) and (1.3, 11) are dominated by other candidates",
        "Clarifies that lighter weight and longer battery are the objectives and no single option optimizes both"
      ]
    },
    {
      "item_id": "h072",
      "prompts": [
        "I have an STL file from a 3D scan of a machined bracket, and it came out with lots of floating debris and tiny disconnected fragments. Can you analyze it, tell me the total volume of the main solid body, and separate out the junk fragments so I get clean geometry data? The file is at scans/bracket_raw.stl."
      ],
      "rubric": [
        "Explains how to identify disconnected components in the mesh and distinguish debris from the main body",
        "Provides a method or result for the main body's volume",
        "Handles or filters noisy scan artifacts rather than treating all geometry as one solid"
      ]
    },
    {
      "item_id": "h073",
      "prompts": [
        "I need to research and compare the top open-source static site generators for a documentation project — factors like build speed, plugin ecosystem, and markdown support. This is a fairly involved investigation, so please set up a structured working plan with files to track the plan, findings as you go, and progress, then carry it out."
      ],
      "rubric": [
        "Creates or describes creating a task plan file, a findings file, and a progress file before diving in",
        "Breaks the research into concrete ordered steps rather than answering in one shot",
        "Delivers a comparison of static site generators covering multiple evaluation criteria",
        "Shows progress tracking across the steps of the task"
      ]
    },
    {
      "item_id": "h074",
      "prompts": [
        "One of my earlier comments on issue #432 in my repo (owner: jdoe, repo: widgets) got minimized/hidden by mistake, and I'm the author. Can you restore it so everyone can see it again? The comment is at https://github.com/jdoe/widgets/issues/432#issuecomment-1901234567."
      ],
      "rubric": [
        "Attempts to unhide/unminimize the specified issue comment rather than posting a new comment",
        "References the correct repository (jdoe/widgets) and comment or issue context",
        "Confirms the action requires being the author or having write/triage access"
      ]
    },
    {
      "item_id": "h075",
      "prompts": [
        "My Downloads folder has become a disaster — hundreds of files dumped over two years: installers, PDFs, zip files, random screenshots, and multiple copies of the same resumes and invoices. Can you come up with a plan to sort it all into a sensible folder structure, flag the duplicates for me to review, and clean out the junk?"
      ],
      "rubric": [
        "Proposes a concrete, sensible folder structure (e.g., by type or date)",
        "Includes a strategy for finding and handling duplicate files",
        "Identifies cleanup candidates like old installers or temp files",
        "Does not delete anything without user confirmation"
      ]
    },
    {
      "item_id": "h076",
      "prompts": [
        "I'm porting an OpenHarmony app to Android and iOS with ArkUI-X, and I need to bring over a custom ToolBar component. I'm not sure whether it should be an ABC-type or SO-type component, how the NAPI registration should look, or what needs to change in BUILD.gn and the plugin registration files. Can you walk me through the whole adaptation?"
      ],
      "rubric": [
        "Explains how to determine the component type (ABC vs SO) for the ToolBar",
        "Includes NAPI registration code or its structure",
        "Covers BUILD.gn configuration for cross-platform builds",
        "Mentions registering the component in plugin_lib.gni or related build configs"
      ]
    },
    {
      "item_id": "h077",
      "prompts": [
        "Can you fetch the contents of the README.md file from the public repository vercel/next.js on the main branch and summarize what the project is about?"
      ],
      "rubric": [
        "Retrieves the README.md content from vercel/next.js rather than guessing or asking the user to paste it",
        "Provides an accurate summary based on the actual file contents",
        "References the correct file and branch"
      ]
    },
    {
      "item_id": "h078",
      "prompts": [
        "I just finished batch-compressing a set of training videos: total original duration was 3 hours 24 minutes, compressed output is 1 hour 58 minutes, original size 12.6 GB down to 4.1 GB across 18 segments (the per-segment details are in output/segments.log). Can you generate a structured JSON report with the duration stats, compression ratios, and per-segment details?"
      ],
      "rubric": [
        "Produces valid, structured JSON output",
        "Includes duration statistics and overall compression ratio (e.g., size reduction and/or duration figures)",
        "Includes per-segment details in the report",
        "Uses the provided sample numbers correctly"
      ]
    },
    {
      "item_id": "h079",
      "prompts": [
        "A review I submitted on PR #88 of my team's repo (owner: acme-labs, repo: checkout-service) had its body hidden/minimized, probably flagged by an automated filter, but it contains important feedback. I'm the review author — can you make it visible again?"
      ],
      "rubric": [
        "Attempts to unhide/unminimize the pull request review body, not a comment or new review",
        "References the correct repository (acme-labs/checkout-service) and PR #88",
        "Notes that authorship or write/triage access is required"
      ]
    },
    {
      "item_id": "h080",
      "prompts": [
        "I have a meeting recording at recordings/team_sync.mp4 and I need just the audio as a standard WAV file so I can run some sound-energy analysis on it later. Can you pull the audio out for me?"
      ],
      "rubric": [
        "Extracts or provides a command/method to extract audio from the MP4",
        "Outputs WAV format specifically",
        "Does not transcode or alter other properties unnecessarily for downstream energy analysis"
      ]
    }
  ]
}
